WITH base AS (SELECT *, LOWER(account_type) AS account_type_lower FROM accounts WHERE opened_date >= DATE '2023-06-30' AND balance BETWEEN 26000 AND 71000) SELECT id, customer_id, account_type, balance, opened_date, status, account_type_lower, LEAD(balance, 1) OVER (PARTITION BY status ORDER BY balance, id) AS next_balance, AVG(balance) OVER (ORDER BY balance, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS balance_avg_2_prior, STDDEV_SAMP(balance) OVER (PARTITION BY status, customer_id) AS status_stddev_samp_balance, SUM(balance) OVER (PARTITION BY status ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_balance FROM base;
